import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());long[] a = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());long totalSum = 0;for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st.nextToken());totalSum += a[i];}if (totalSum % 3 != 0) {System.out.println(0);return;}long target = totalSum / 3;long currentSum = 0;long countFirstPart = 0;long ans = 0;for (int i = 0; i < n - 1; i++) {currentSum += a[i];if (i > 0 && currentSum == 2 * target) {ans += countFirstPart;}if (currentSum == target) {countFirstPart++;}}System.out.println(ans);}}